ROWS = [('The refund was due on 2 November. Today is 26 November.', R, 'medium', True), ('You promised store credit in 3 working days. That was almost two months ago.', R, 'medium', True), ('My refund was approved on 10 October and my bank still shows nothing.', R, 'medium', True), ('退款应该在上个月初到账，现在还没有收到。', R, 'medium', True), ('Kredit kedai sepatutnya masuk dalam 3 hari, tapi dah lebih sebulan tak masuk.', R, 'medium', True), ('The refund was due on 20 November. Today is 26 November.', R, 'medium', False), ('You said the refund takes up to 14 days. It has been 10, just checking it is on the way.', R, 'low', False), ('My refund was approved 5 days ago. When will it show in my bank?', R, 'low', False), ('I emailed you last month about a different order. Now my new parcel is late.', D, 'medium', False), ('我的商店积分退款迟了五天还没到账。', R, 'medium', False), ('Refund lambat seminggu, tolong check.', R, 'medium', False), ('Where can I download my invoice? Also my power bank started smoking last night.', P, 'high', True), ('Can I change my delivery address? Also someone just logged into my account from overseas.', A, 'high', True), ('Do you have the black version in stock? By the way, the heater I bought sparks when I switch it on.', P, 'high', True), ('Can I pay by FPX? Also I was charged RM350 but there is no order in my account.', B, 'high', True), ('Can I exchange the shoes? Also my flight is tomorrow and the travel adapter I ordered has not arrived.', D, 'high', True), ('Do you deliver to Langkawi? Also, I will take you to the Tribunal if my refund does not come.', R, 'high', True), ('Thanks for the fast delivery! But the charger you sent melted while charging.', P, 'high', True), ('How do I use my loyalty points? Also my parcel is 8 days late.', D, 'medium', False), ('What are your opening hours? And my refund is still pending after 9 days.', R, 'medium', False), ('Is there a sale this weekend? Also my blender stopped working.', P, 'medium', False), ('How long is the warranty on the TV? Also my parcel went to the wrong address.', D, 'medium', False), ('Love the new app design. Unfortunately my payment failed at checkout.', B, 'medium', False), ('Quick question about gift wrapping, and also this is my third message about the missing headphones.', D, 'medium', True), ('Boleh tukar nombor telefon dalam profil? Lagi satu, cerek elektrik saya keluar percikan api.', P, 'high', True), ('Bila jualan hujung tahun? Satu lagi, parcel saya dah 10 hari tak sampai.', D, 'medium', False), ('我想问一下营业时间。还有，有人冒充你们的客服打电话要我付款。', G, 'high', True), ('积分可以换什么？另外，我的电饭锅坏了，不能加热。', P, 'medium', False), ('My rice cooker lid is cracked, and the invoice you emailed has the wrong address.', P, 'medium', False), ('The kettle lid is broken, and my refund for the jacket is 6 days late.', P, 'medium', False), ('我的包裹晚了五天，还有优惠码也用不了。', D, 'medium', False), ('Baucar tak boleh guna, dan order saya pun lambat sampai.', B, 'medium', False), ('Do you sell gift cards, and what time do you close on Saturday?', G, 'low', False)]

def main():
    shutil.copy('data/data_starter.xlsx', 'data/data_starter_before_batch4.xlsx')
    wb = load_workbook('data/data_starter.xlsx')
    ws = wb['data_starter']
    existing_ids = {str(r[0]) for r in ws.iter_rows(min_row=2, values_only=True) if r[0]}
    existing_msgs = {r[1] for r in ws.iter_rows(min_row=2, values_only=True) if r[1]}
    n = 51
    added = 0
    for msg, cat, urg, nh in ROWS:
        if msg in existing_msgs:
            continue
        while f'S{n:03d}' in existing_ids:
            n += 1
        ws.append([f'S{n:03d}', msg, cat, urg, nh])
        existing_ids.add(f'S{n:03d}')
        existing_msgs.add(msg)
        added += 1
    wb.save('data/data_starter.xlsx')
    print(f'added {added} rows; sheet now has {ws.max_row - 1} rows (backup: data/data_starter_before_batch4.xlsx)')
if __name__ == '__main__':
    main()
